#include <assert.h>
#include <stdio.h>
#include <string.h>
#include "core/focus_flow.h"
static void add(focus_flow *f){flow_action(f,"add");flow_action(f,"talk");assert(f->page==P_RECORD);f->heard=true;strcpy(f->draft,"prepare report");flow_action(f,"talk");assert(f->page==P_CONFIRM);flow_action(f,"confirm");assert(f->page==P_ADD);}
static void ready(focus_flow *f){flow_init(f);add(f);flow_action(f,"list");flow_action(f,"select");flow_action(f,"minutes 15");assert(f->page==P_PREPARE);}
int main(void){focus_flow f;ready(&f);flow_action(&f,"start");assert(f.page==P_WAIT);flow_tick(&f,50);assert(f.remaining==900);flow_phone(&f,true);flow_poll(&f,649);assert(f.page==P_WAIT);flow_poll(&f,1);assert(f.page==P_RUNNING);flow_tick(&f,10);assert(f.remaining==890);flow_phone(&f,false);flow_poll(&f,650);assert(f.page==P_PAUSED&&f.phone_pause);flow_tick(&f,10);assert(f.remaining==890);flow_phone(&f,true);flow_poll(&f,650);assert(f.page==P_RUNNING);flow_action(&f,"pause");flow_phone(&f,false);flow_poll(&f,650);flow_phone(&f,true);flow_poll(&f,650);assert(f.page==P_PAUSED);flow_action(&f,"home");flow_phone(&f,true);flow_poll(&f,650);assert(f.page==P_STANDBY);flow_action(&f,"enter");flow_action(&f,"today");assert(f.page==P_PAUSED);flow_action(&f,"resume");assert(f.page==P_RUNNING);flow_action(&f,"end");flow_phone(&f,false);flow_poll(&f,650);flow_action(&f,"cancel-end");assert(f.page==P_WAIT);flow_action(&f,"cancel-wait");flow_phone(&f,true);flow_poll(&f,650);assert(f.page==P_PAUSED);flow_action(&f,"resume");flow_action(&f,"timeout");assert(f.page==P_REVIEW&&!f.tasks[0].done);flow_action(&f,"home");flow_action(&f,"enter");flow_action(&f,"today");assert(f.page==P_REVIEW);flow_action(&f,"done");assert(f.tasks[0].done&&f.page==P_SUMMARY);flow_action(&f,"list");assert(f.page==P_LIST&&f.cursor==-1);
ready(&f);flow_action(&f,"start");flow_action(&f,"bypass");flow_phone(&f,false);flow_poll(&f,650);assert(f.page==P_RUNNING);flow_tick(&f,1000);assert(f.page==P_REVIEW&&f.total_seconds==900);flow_action(&f,"continue");assert(f.page==P_PREPARE&&!f.bypass);
flow_init(&f);flow_action(&f,"add");flow_action(&f,"talk");flow_tick(&f,1000);assert(f.page==P_RECORD);flow_action(&f,"talk");assert(f.page==P_ADD&&f.count==0);add(&f);add(&f);assert(f.count==2&&f.tasks[0].id!=f.tasks[1].id);
ready(&f);flow_action(&f,"start");flow_phone(&f,true);flow_poll(&f,300);flow_phone(&f,false);flow_poll(&f,650);assert(f.page==P_WAIT);flow_phone(&f,true);flow_poll(&f,650);assert(f.page==P_RUNNING);
puts("PASS: intake, manual endpoint, dock gate, debounce, pause ownership, Home, review, bypass, repeat rounds");return 0;}
